//router 工站（天书）lite
import {
  createRouter,
  // createWebHistory,
  createWebHashHistory
} from 'vue-router'

const routes = [
  {
    path: '/',
    redirect: '/status'
  },
  {
    //status 工站（天书）lite
    path: '/status',
    component: () => import('@/views/status/index-tg.vue')
  },
  {
    path: '/devices',
    component: () => import('@/views/devices/index.vue')
  },
  // 设备二级菜单-开始
  {
    path: '/devices/joint',
    component: () => import('@/views/devices/joint/index.vue')
  },
  // {
  //   path: '/devices/power',
  //   component: () => import('@/views/devices/power/index.vue')
  // },
  // 设备二级菜单-结束
  {
    path: '/alarm',
    component: () => import('@/views/alarm/index.vue')
  },
  {
    path: '/topic',
    component: () => import('@/views/topic/index.vue')
  },
  {
    path: '/version',
    component: () => import('@/views/version/index.vue')
  },
  {
    path: '/log',
    component: () => import('@/views/log/index.vue')
  }
]

const router = createRouter({
  // history: createWebHistory('/'), // 使用 history 模式
  history: createWebHashHistory('/'), // 使用 hash 模式
  routes
})

export default router
